create or replace function public.erp_qms_protect_revision() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ begin if old.status in ('aprovada','liberada','vigente') then if new.revisao<>old.revisao or coalesce(new.titulo,'')<>coalesce(old.titulo,'') or coalesce(new.conteudo,'')<>coalesce(old.conteudo,'') or coalesce(new.motivo_alteracao,'')<>coalesce(old.motivo_alteracao,'') then raise exception 'Revisão aprovada/liberada/vigente é imutável. Crie uma nova revisão.'; end if; end if; return new; end $$;
drop trigger if exists trg_erp_qms_protect_revision on public.erp_documentos_qualidade_revisoes;
create trigger trg_erp_qms_protect_revision before update on public.erp_documentos_qualidade_revisoes for each row execute function public.erp_qms_protect_revision();
insert into public.erp_permissoes_modulos(empresa_id,setor_id,modulo,visualizar,criar,editar,solicitar_alteracao,revisar,aprovar,liberar,bloquear)
select s.empresa_id,s.id,'qualidade_documentos',true,false,false,true,false,false,false,false from public.erp_setores s where s.empresa_id='cc1b66d4-9f1e-4ad2-82d7-377ce1406be1' and s.ativo=true and s.codigo<>'QUALIDADE'
on conflict (empresa_id,usuario_id,setor_id,modulo) do update set visualizar=excluded.visualizar,criar=excluded.criar,editar=excluded.editar,solicitar_alteracao=excluded.solicitar_alteracao;
insert into public.erp_permissoes_modulos(empresa_id,setor_id,modulo,visualizar,criar,editar,solicitar_alteracao,revisar,aprovar,liberar,bloquear)
select s.empresa_id,s.id,'qualidade_documentos',true,true,true,true,true,true,true,true from public.erp_setores s where s.empresa_id='cc1b66d4-9f1e-4ad2-82d7-377ce1406be1' and s.codigo='QUALIDADE'
on conflict (empresa_id,usuario_id,setor_id,modulo) do update set visualizar=excluded.visualizar,criar=excluded.criar,editar=excluded.editar,solicitar_alteracao=excluded.solicitar_alteracao,revisar=excluded.revisar,aprovar=excluded.aprovar,liberar=excluded.liberar,bloquear=excluded.bloquear;